const desc={dashboard:n+' '+(n===1?'store':'stores')+'. B&B Management and parent companies stay separate.',banking:'Cash and spend across your stores: what is in the bank, what went out on cards, and what you owe.',books:'Closed QuickBooks months across your stores, side by side.',payroll:'Labor cost, paid hours and schedules across your stores.',insurance:'Policies by store, upcoming renewals and coverage gaps.'}[view]||'Review each store, then open its records for the details.';
